<?php $nav=array('admin/dashboard'=>array('⌂','Overview'),'admin/customers'=>array('♙','Customers'),'admin/transactions'=>array('⇄','Transactions'),'admin/transfers'=>array('↗','Transfers'),'admin/deposits'=>array('+','Deposits'),'admin/loans'=>array('▥','Loans'),'admin/cards'=>array('▤','Cards'),'admin/tickets'=>array('◫','Support tickets'),'admin/tutorial'=>array('▷','Tutorial'),'admin/audit_logs'=>array('⇉','Audit log'),'admin/settings'=>array('⚙','System settings'));foreach($nav as $url=>$item):?><a href="<?=site_url($url)?>" class="<?=$current_route===$url?'active':''?>"><i><?=$item[0]?></i><?=$item[1]?></a><?php endforeach?></nav><div class="aside-foot"><a href="<?=site_url('admin/logout')?>">⇥ Sign out</a><div class="secure">✓ <span><b>Secure session</b><small>Administrator portal</small></span></div></div></aside><main><header><button class="menu" data-menu>☰</button><div class="search">⌕ <input placeholder="Search customers, transactions..." data-search="<?=site_url('admin/customers')?>"></div><div class="head-user"><div class="bell-wrap"><button class="bell" data-bell>♢<i></i></button><div class="bell-drop" hidden><div class="bell-head">Recent activity</div><div class="bell-list"><?php foreach($notifications as $n):?><a href="<?=site_url('admin/transactions')?>"><b class="<?=$n['type']==='credit'?'credit':''?>"><?=$n['type']==='credit'?'+':'−'?> <?=money($n['amount'],$n['currency'])?></b><span><?=html_escape($n['description'])?></span><small><?=html_escape($n['first_name']??'').' '.html_escape($n['last_name']??'')?> · <?=date('M j, g:i a',strtotime($n['created_at']))?></small></a><?php endforeach?><?php if(!$notifications):?><div class="bell-empty">No recent activity.</div><?php endif?></div></div></div><span class="avatar"><?=initials($current_user['first_name'].' '.$current_user['last_name'])?></span><div><b><?=html_escape($current_user['first_name'].' '.$current_user['last_name'])?></b><small>Super administrator</small></div></div></header><div class="p